window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[38]={"id":"038","numero":38,"titre":"Infertilité du couple","objectifs":[{"id":"38-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","contenu":"<div class=\"notion-course\"><ul><li><b>Fertilité :</b> capacité biologique à concevoir. Elle est potentielle et ne se résume pas au nombre d’enfants déjà nés.</li><li><b>Fécondité :</b> réalisation effective de la reproduction, appréciée notamment par les naissances. En démographie, les indicateurs de fécondité mesurent les naissances dans une population.</li><li><b>Fécondabilité :</b> probabilité d’obtenir une grossesse au cours d’un cycle exposé. Ne pas la confondre avec la probabilité cumulée sur six ou douze mois.</li><li>L’âge ovocytaire influence fortement la fécondabilité et le risque de fausse couche ; la baisse s’accentue avec l’âge, notamment après 35 ans. Les probabilités dépendent aussi de la durée des essais et des facteurs féminins et masculins.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":0},{"id":"38-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un couple infertile","contenu":"<div class=\"notion-course\"><ul><li><b>Infertilité :</b> absence de grossesse après au moins douze mois de rapports réguliers sans contraception. <b>Primaire :</b> aucune grossesse antérieure ; <b>secondaire :</b> après une grossesse antérieure, quelle qu’en ait été l’issue.</li><li><b>Bilan plus précoce :</b> à six mois lorsque la femme a plus de 35 ans, et sans attendre ce délai si aménorrhée, pathologie tubaire ou masculine connue, traitement gonadotoxique ou autre facteur majeur. Au-delà de 40 ans, une évaluation rapide est justifiée.</li><li>Évaluer les deux partenaires simultanément : antécédents, durée des essais, cycles, <span class=\"nc-green_bg\">fréquence des rapports</span>, difficultés sexuelles et facteurs de risque. Des rapports réguliers, environ tous les deux à trois jours, évitent un calendrier trop contraignant.</li><li>Infertilité ne signifie pas stérilité définitive ; le bilan et le pronostic dépendent du contexte.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":0},{"id":"38-3","rang":"B","rubrique":"Epidémiologie, prévalence","titre":"Connaître la fertilité et fécondité dans la population générale","contenu":"<div class=\"notion-course\"><p>La fertilité spontanée du couple est <strong>fortement dépendante de l’âge maternel</strong>. La <span class=\"nc-red nc-bold\">réserve ovarienne en follicules ovariens diminue </span><span><span class=\"nc-red nc-bold\">de façon physiologique avec l’âge en qualité et quantité</span></span> — phénomène irréversible.</p>\n\n      <h4>Courbe de fertilité féminine selon l’âge</h4>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 190\" role=\"img\" aria-label=\"Courbe du déclin de la fertilité féminine selon l&#x27;âge : probabilité de grossesse à 6 mois d&#x27;environ 60 % avant 25 à 28 ans (pic), début du déclin dès 31 ans, 30 % à 35 ans qui est le seuil opérationnel, et fertilité presque nulle après 45 ans.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"14\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Déclin de la fertilité féminine avec l'âge</text>\n          <line class=\"ln\" x1=\"60\" y1=\"30\" x2=\"60\" y2=\"160\" stroke-width=\"1.5\"></line>\n          <line class=\"ln\" x1=\"60\" y1=\"160\" x2=\"515\" y2=\"160\" stroke-width=\"1.5\"></line>\n          <text class=\"tx-muted\" x=\"52\" y=\"43\" text-anchor=\"end\" font-size=\"8\"><span>60 %</span></text>\n          <text class=\"tx-muted\" x=\"52\" y=\"103\" text-anchor=\"end\" font-size=\"8\"><span>30 %</span></text>\n          <text class=\"tx-muted\" x=\"52\" y=\"163\" text-anchor=\"end\" font-size=\"8\"><span>0 %</span></text>\n          <polyline class=\"ln\" fill=\"none\" stroke-width=\"2.5\" points=\"90,40 230,52 340,100 480,158\"></polyline>\n          <circle class=\"fb-ok\" cx=\"90\" cy=\"40\" r=\"4\"></circle>\n          <circle class=\"fb-amber\" cx=\"230\" cy=\"52\" r=\"4\"></circle>\n          <circle class=\"fb-red\" cx=\"340\" cy=\"100\" r=\"4.5\"></circle>\n          <circle class=\"fb-grey\" cx=\"480\" cy=\"158\" r=\"4\"></circle>\n          <text class=\"tx-ok\" x=\"98\" y=\"34\" font-size=\"8\" font-weight=\"600\">pic (<span>60 %</span>)</text>\n          <text class=\"tx-amber\" x=\"222\" y=\"44\" text-anchor=\"middle\" font-size=\"8\">début du déclin</text>\n          <text class=\"tx-red\" x=\"348\" y=\"96\" font-size=\"8.5\" font-weight=\"700\"><span>30 %</span> — seuil <span>35 ans</span></text>\n          <text class=\"tx-grey\" x=\"478\" y=\"150\" text-anchor=\"end\" font-size=\"8\">≈ nulle</text>\n          <text class=\"tx-muted\" x=\"90\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span>25 ans</span></text>\n          <text class=\"tx-muted\" x=\"230\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span>31 ans</span></text>\n          <text class=\"tx-muted\" x=\"340\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span>35 ans</span></text>\n          <text class=\"tx-muted\" x=\"480\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">&gt;<span> 45 ans</span></text>\n        </svg>\n        <figcaption>Probabilité de <span>grossesse</span> à<span> 6 mois</span> selon l'âge maternel : pic avant <span>25-28 ans</span>, déclin dès <span>31 ans</span>, <strong><span>35 ans</span> = seuil opérationnel</strong> (raccourcir le délai avant bilan), quasi nulle après <span>45 ans</span>.</figcaption>\n      </figure>\n\n      <table>\n        <thead>\n          <tr><th>Âge maternel</th><th>Probabilité de grossesse à <span>6 mois</span></th><th>Commentaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span> 25-28 ans</span></strong></td>\n            <td><span>60 %</span></td>\n            <td>Pic de fertilité ; recul de l’âge à la 1ʳᵉ <span>grossesse</span> = enjeu démographique</td>\n          </tr>\n          <tr>\n            <td><strong><span>31 ans</span></strong></td>\n            <td>—</td>\n            <td><span>Début du déclin</span> (mesurable mais lent)</td>\n          </tr>\n          <tr>\n            <td><strong><span>35 ans</span></strong></td>\n            <td><span>30 %</span></td>\n            <td>Chute marquée — seuil opérationnel pour <strong>raccourcir le délai avant bilan</strong></td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span> 45 ans</span></strong></td>\n            <td><span>≈ 0 %</span></td>\n            <td>Fertilité <span>presque nulle</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs pronostiques principaux (femme)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Facteur</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Réserve ovarienne décroît qualitativement et quantitativement</td>\n          </tr>\n          <tr>\n            <td><strong>Poids</strong></td>\n            <td>\n              <strong>IMC <span class=\"nc-red nc-bold\">&gt;</span><span><span class=\"nc-red nc-bold\"> 30 kg/m²</span></span> :</strong> chances de <span>grossesse</span> divisées par <span>4</span> ; <br>\n              <strong>IMC <span class=\"nc-red nc-bold\">trop bas</span> :</strong> troubles de l’ovulation (<span class=\"nc-yellow_bg\">anovulation</span> <span class=\"nc-orange_bg\">hypothalamique</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Tabac</span></strong></td>\n            <td>\n              Diminution dose-dépendante : <span>↑ délai de conception</span> ; <br>\n              ↑ risque de <span>fausses couches, <span class=\"nc-red_bg\">GEU</span>, <span class=\"nc-red_bg\">RCIU</span>, mort fœtale in utero</span> ; <br>\n              ↑ risque de <span><span class=\"nc-orange_bg\">placenta praevia</span>, HRP, RPM</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Fertilité masculine</h4>\n\n      <p>L’âge paternel est <span>également associé à une diminution de la fertilité spontanée</span>, mais <strong>sans seuil précis</strong> (contrairement à la femme). Relation dose-effet entre <strong>IMC élevé</strong> et hypofertilité d’origine masculine.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 124 — Ménopause - andropause</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":1},{"id":"38-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez la femme","contenu":"<div class=\"notion-course\"><p>Le bilan d’infertilité chez la femme est <strong>systématique et structuré</strong> en 4 axes : <span>interrogatoire / terrain</span>, <span>symptômes ciblés</span>, <span>examen clinique</span>, <span>dépistage</span>.</p>\n\n      <h4>Interrogatoire — <span>Terrain</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD gynéco-obstétricaux</strong></td>\n            <td>\n              <strong>Gestité, parité :</strong> grossesses antérieures, IVG anciennes (++) ; <br>\n              <strong>IST, <span class=\"nc-orange_bg\">salpingite</span> :</strong> Chlamydia ++ ; <br>\n              <strong><span>Chirurgie</span> pelvienne :</strong> appendicite compliquée, myomectomie (risque d’adhérences) ; <br>\n              <strong>Chirurgie ovarienne :</strong> risque d’<span>insuffisance ovarienne</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span>Diabète, épilepsie, maladies auto-immunes</span> — pouvant retentir sur une future <span>grossesse</span> ou nécessiter une programmation</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux</strong></td>\n            <td>Pathologies génétiques, thrombophilies / ATCD thromboemboliques, ménopause précoce, <span class=\"nc-red\">cancer</span> du sein, <span>diabète</span>…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés (recherche orientée)</h4>\n\n      <ul>\n        <li><strong>Durée et régularité des cycles</strong> → recherche d’un trouble de l’<span>ovulation</span></li>\n        <li><span>Dysménorrhée</span>, <span>dyspareunie profonde</span> → évoque une <strong>endométriose</strong></li>\n        <li><span>Bouffées de chaleur</span> → en faveur d’une <strong>insuffisance ovarienne prématurée (IOP)</strong></li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Général</strong></td>\n            <td>Morphotype, <span>IMC</span>, signes d’<span>hyperandrogénie</span> (hirsutisme, acné), <span>acanthosis nigricans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Recherche d’une <span>galactorrhée</span> s’il existe des troubles du cycle (<strong>hyperprolactinémie</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologique</strong></td>\n            <td>\n              Malformation <span class=\"nc-red nc-bold\">génitale</span> ; <br>\n              Signes indirects d’<span class=\"nc-orange_bg\">endométriose</span> (<span>utérus rétroversé, douleurs au TV</span>) ; <br>\n              Trophicité vaginale, état du col, présence de <span>gros fibromyomes utérins</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Dépistage</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>FCV de <span>dépistage</span></strong> si le dernier date de <span><span class=\"nc-pink nc-bold\">&gt; 3 ans</span></span>. Précède l’<span class=\"nc-blue_bg\">hystéro-salpingographie</span> (interprétation difficile si pathologie cervicale méconnue).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 162 — IST · 244 — Adénome hypophysaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":0},{"id":"38-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez l’homme","contenu":"<div class=\"notion-course\"><p>Bilan clinique masculin = <strong>4 axes</strong> : <span>terrain</span> (toxiques, ATCD), symptômes (sexualité), examen (verge / volume <span class=\"nc-red\">testiculaire</span> / <span class=\"nc-red\">varicocèle</span>), distracteurs annales.</p>\n\n      <h4>Interrogatoire — <span>Terrain</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td>Exposition aux <span>toxiques</span> : chaleur, <strong><span class=\"nc-blue nc-bold\">pesticides</span></strong>, <strong>polluants organochlorés</strong>, <span class=\"nc-blue_bg\">hydrocarbures</span>, <span class=\"nc-blue_bg\">solvants</span>, <span class=\"nc-blue_bg\">perturbateurs endocriniens</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxiques personnels</strong></td>\n            <td><span><span class=\"nc-red\">Tabac</span>, <span class=\"nc-red\">cannabis</span></span> ; quantification de l’<span><span class=\"nc-red nc-bold\">alcool</span></span> ; <span>dopage à la <span class=\"nc-pink\">testostérone</span> et/ou <span class=\"nc-pink\">anabolisants</span> (+++)</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD génitaux</strong></td>\n            <td>\n              <strong>Ectopie <span class=\"nc-red\">testiculaire</span> / cryptorchidie (+++)</strong> ; <br>\n              Torsion ou traumatisme <span class=\"nc-red\">testiculaire</span> ; <br>\n              <span class=\"nc-purple_bg\">Infections (</span><span><span class=\"nc-purple_bg\">IST, oreillons</span></span><span class=\"nc-purple_bg\">)</span> ; <br>\n              <span class=\"nc-orange_bg\">ATCD d’</span><span><span class=\"nc-orange_bg\">hernie</span> inguinale bilatérale opérée</span> (<span>lésion</span> des déférents et/ou vascularisation <span class=\"nc-red\">testiculaire</span>) ; <br>\n              Orchidopexie pour torsion du cordon spermatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span><span class=\"nc-orange_bg\">Mucoviscidose</span></span> (sinusites et bronchites à répétition)</td>\n          </tr>\n          <tr>\n            <td><strong>Traitements</strong></td>\n            <td><span>Chimiothérapie</span>, radiothérapie, <strong><span class=\"nc-pink nc-bold\">psychotropes</span></strong>, <strong><span class=\"nc-pink nc-bold\">anticonvulsivants</span></strong>, <strong><span class=\"nc-pink nc-bold\">stéroïdes</span></strong>, <strong>α-bloquants</strong>, <strong>inhibiteurs de la 5α-réductase</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés</h4>\n\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Dysfonction sexuelle</span></span> : troubles de la libido, de l’érection, de l’éjaculation</li>\n        <li>Douleurs uro-génitales → infection (épididymite, <span>prostatite</span>) ou <strong>varicocèle</strong></li>\n        <li>Signes digestifs ou respiratoires → <span>mucoviscidose</span> (à explorer si évocateur)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Morphotype</strong></td>\n            <td>Aspect <span>gynoïde, eunuchoïde</span>, <span class=\"nc-blue_bg\">taille/poids</span>, évaluation de la pilosité, <span class=\"nc-blue_bg\">gynécomastie bilatérale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’hypoandrisme</strong></td>\n            <td><span class=\"nc-blue_bg\">Faible pilosité</span>, <span class=\"nc-blue_bg\">faible </span><span><span class=\"nc-blue_bg\">masse</span></span><span class=\"nc-blue_bg\"> musculaire</span>, <span class=\"nc-blue_bg\">adiposité augmentée</span></td>\n          </tr>\n          <tr>\n            <td><strong>Verge et appareil externe</strong></td>\n            <td>Hypospadias, infection du méat, présence des épididymes, des <span class=\"nc-purple nc-bold\">canaux déférents</span>, cicatrices chirurgicales</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red\">Varicocèle</span></strong></td>\n            <td>Recherché en position debout + <span>manœuvre de Valsalva</span>. <strong>Grader chaque côté</strong> (<span>1, 2 ou 3</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Volume <span class=\"nc-red\">testiculaire</span></strong></td>\n            <td>Mesuré à l’<span>orchidomètre de Prader</span>. Volume normal = <span><span class=\"nc-pink nc-bold\">15-20 mL</span></span>. ≈<span>80 %</span> du volume est constitué par les <strong>tubes séminifères</strong></td>\n          </tr>\n          <tr>\n            <td><strong>TR</strong></td>\n            <td>Non systématique. Recommandé si : ATCD <span>infectieux</span>, hypospermie, anomalie du plasma séminal, suspicion de déficit androgénique, ou âge justifiant la recherche d’un <span class=\"nc-red\">cancer</span> de la prostate</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales (à ne pas rechercher dans ce contexte).</strong>\n        <ul>\n          <li><span>Signe de Prehn</span> → évoque une <strong>orchi-épididymite</strong>, pas une infertilité</li>\n          <li>Gynécomastie <strong>unilatérale</strong> n’oriente pas vers une infertilité (origine endocrinienne ⇒ généralement bilatérale)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":1,"liens":[{"href":"https://fr.wikipedia.org/wiki/Orchidom%C3%A8tre","label":"Wikipedia — Orchidomètre (volume testiculaire)"}]},{"id":"38-6","rang":"B","rubrique":"Étiologies","titre":"Connaître l’orientation diagnostique en fonction du contexte et des manifestations associées","contenu":"<div class=\"notion-course\"><p>L’orientation étiologique se construit en croisant <strong>répartition des causes</strong>, <strong>facteurs pronostiques majeurs</strong> et <strong>signes d’appel</strong> orientant vers un mécanisme dominant (ovulatoire / tubaire / utérin / cervical / <span class=\"nc-orange_bg\">endométriose</span> / masculin).</p>\n\n      <h4>Répartition des étiologies d’<span class=\"nc-blue_bg\">infertilité</span> féminine (à connaître)</h4>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 196\" role=\"img\" aria-label=\"Répartition des étiologies d&#x27;infertilité féminine par fréquence : anovulations et dysovulations 40 %, étiologies tubo-péritonéales 30 %, endométriose 15 %, étiologies cervicales 4 %, étiologies utérines 4 %, sexologiques 2 %, autres 5 %.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Étiologies d'infertilité féminine — fréquence</text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"30\" width=\"300\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"41.5\" font-size=\"8.5\">Anovulation / dysovul.</text>\n          <text class=\"tx-blue\" x=\"486\" y=\"41.5\" font-size=\"9\" font-weight=\"700\"><span>40 %</span></text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"54\" width=\"225\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"65.5\" font-size=\"8.5\">Tubo-péritonéales</text>\n          <text class=\"tx-blue\" x=\"411\" y=\"65.5\" font-size=\"9\" font-weight=\"700\"><span>30 %</span></text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"78\" width=\"112\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"89.5\" font-size=\"8.5\">Endométriose</text>\n          <text class=\"tx-blue\" x=\"298\" y=\"89.5\" font-size=\"9\" font-weight=\"700\"><span>15 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"102\" width=\"30\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"113.5\" font-size=\"8.5\">Cervicales</text>\n          <text class=\"tx-grey\" x=\"216\" y=\"113.5\" font-size=\"9\" font-weight=\"700\"><span>4 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"126\" width=\"30\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"137.5\" font-size=\"8.5\">Utérines</text>\n          <text class=\"tx-grey\" x=\"216\" y=\"137.5\" font-size=\"9\" font-weight=\"700\"><span>4 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"150\" width=\"15\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"161.5\" font-size=\"8.5\">Sexologiques</text>\n          <text class=\"tx-grey\" x=\"201\" y=\"161.5\" font-size=\"9\" font-weight=\"700\"><span>2 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"174\" width=\"38\" height=\"15\" rx=\"3\"></rect>\n          <text class=\"tx-muted\" x=\"8\" y=\"185.5\" font-size=\"8.5\">Autres</text>\n          <text class=\"tx-grey\" x=\"224\" y=\"185.5\" font-size=\"9\" font-weight=\"700\"><span>5 %</span></text>\n        </svg>\n        <figcaption>Trois causes dominent (anovulation <span>40 %</span> &gt; tubo-péritonéal <span>30 %</span> &gt; endométriose <span>15 %</span>) — total <span>100 %</span>. Ordre de fréquence à connaître.</figcaption>\n      </figure>\n\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Anovulations / dysovulations</strong></td><td><span>40 %</span></td></tr>\n          <tr><td><strong>Étiologies tubo-péritonéales</strong></td><td><span>30 %</span></td></tr>\n          <tr><td><strong>Endométriose</strong></td><td><span>15 %</span></td></tr>\n          <tr><td>Étiologies cervicales</td><td><span>4 %</span></td></tr>\n          <tr><td>Étiologies utérines</td><td><span>4 %</span></td></tr>\n          <tr><td>Sexologiques (dysfonctions du couple)</td><td><span>2 %</span></td></tr>\n          <tr><td>Autres</td><td><span>5 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’appel → orientation</h4>\n\n      <table>\n        <thead>\n          <tr><th>Signe d’appel</th><th>Mécanisme évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Aménorrhée ou cycles irréguliers</span></td>\n            <td><span><span class=\"nc-yellow_bg\">Anovulation</span></span> (<span>20 %</span> des infécondités) — explorer <span><span class=\"nc-orange_bg\">SOPK</span></span>, <span><span class=\"nc-orange_bg\">hyperprolactinémie</span></span>, <span><span class=\"nc-orange_bg\">IOP</span></span>, déficit gonadotrope</td>\n          </tr>\n          <tr>\n            <td>Cycles réguliers (28 ± j)</td>\n            <td>N’élimine pas une <span class=\"nc-yellow_bg\">anovulation</span> — <span>progestéronémie J22-23</span> obligatoire</td>\n          </tr>\n          <tr>\n            <td>Hirsutisme, acné, acanthosis nigricans</td>\n            <td><span>SOPK</span> ; doser <span>17OH-progestérone</span>, <span><span class=\"nc-blue_bg\">testostérone totale</span></span><span class=\"nc-blue_bg\">,</span> Δ<span <span=\"\">&gt;4</span> androstènedione, SDHEA</td>\n          </tr>\n          <tr>\n            <td>Galactorrhée, troubles du cycle</td>\n            <td><span><span class=\"nc-orange_bg\">Hyperprolactinémie</span></span> (<span>adénome <span class=\"nc-orange_bg\">hypophysaire</span></span>) — <span><span class=\"nc-blue_bg\">prolactine</span></span> + <span><span class=\"nc-blue_bg\">TSH</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Bouffées de chaleur</span></td>\n            <td><span>Insuffisance ovarienne prématurée (IOP)</span></td>\n          </tr>\n          <tr>\n            <td><span>Dysménorrhée, dyspareunie profonde</span>, utérus rétroversé</td>\n            <td><span>Endométriose</span> (<span>4 %</span> population, <span>30-50 %</span> des femmes infertiles)</td>\n          </tr>\n          <tr>\n            <td>ATCD de <span><span class=\"nc-orange_bg\">salpingite</span></span>, <span>Chlamydia</span>, <span>chirurgie</span> pelvienne</td>\n            <td><span>Cause tubaire</span> (cause majeure d’infertilité féminine)</td>\n          </tr>\n          <tr>\n            <td>ATCD de conisation / <span>curetage</span> / diathermo</td>\n            <td>Pathologie cervicale (sténose, glaire) → indication d’<span>IAC</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Des cycles cliniquement réguliers <strong>n’éliminent pas</strong> une <span class=\"nc-yellow_bg\">anovulation</span> — la <span>progestéronémie au 22-23ᵉ jour</span> reste obligatoire dès qu’il existe une suspicion clinique.\n      </div>\n\n      <h4>Facteurs pronostiques majeurs (femme et homme)</h4>\n\n      <ul>\n        <li><strong>Âge</strong> — facteur N°1 chez la femme (effondrement de la réserve folliculaire après <span>35 ans</span>)</li>\n        <li><strong>Poids</strong> — IMC &gt; 30 = ÷4 chances de <span>grossesse</span> ; IMC <span class=\"nc-red nc-bold\">trop bas</span> = troubles de l’ovulation</li>\n        <li><strong><span>Tabac</span></strong> — dose-dépendant, ↑ délai de conception, fausses couches, <span class=\"nc-red_bg\">GEU</span>, <span class=\"nc-red_bg\">RCIU</span>, MFIU</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 244 — Adénome hypophysaire · 124 — Ménopause - andropause</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":2},{"id":"38-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention d’une infertilité féminine et/ou masculine","contenu":"<div class=\"notion-course\"><ul><li>Évaluer simultanément les deux partenaires concernés, avec interrogatoire, examen et prise en compte de l’âge, de la durée d’<span class=\"nc-blue_bg\">infertilité</span> et des facteurs de risque.</li><li>Chez la femme : documenter les cycles et l’<span class=\"nc-red nc-bold\">ovulation</span>, <span class=\"nc-yellow_bg\">échographie pelvienne</span>, bilan hormonal ciblé selon contexte ; évaluation tubaire par hystérosalpingographie ou méthode échographique appropriée si indiquée.</li><li><span class=\"nc-blue_bg\">AMH</span> et compte des follicules antraux renseignent sur la réserve ovarienne et surtout la réponse attendue à une stimulation ; ils ne prédisent pas à eux seuls la possibilité d’une grossesse spontanée.</li><li>Chez l’homme : spermogramme/spermocytogramme, avec conditions de recueil ; <span class=\"nc-blue_bg\">spermoculture</span> selon bilan/projet. Un résultat anormal nécessite confirmation et orientation adaptée.</li><li>Le test post-coïtal de Hühner n’est pas recommandé en routine. Pas de cœlioscopie ou d’<span class=\"nc-blue_bg\">hystéroscopie</span> systématique sans indication.</li><li>Orienter plus tôt si âge maternel élevé, aménorrhée, pathologie tubaire, <span class=\"nc-orange_bg\">endométriose</span> significative ou anomalie spermatique sévère ; ne pas imposer un an d’attente dans toutes les situations.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/38/bilan-1ere-intention-fig1.png\" alt=\"Schéma de synthèse du bilan paraclinique de 1ère intention dans l&#x27;infertilité du couple (femme et homme), tiré de la fiche source EDN item 38\" loading=\"lazy\">\n        <figcaption>Vue 1 — synthèse du bilan paraclinique de 1ʳᵉ intention (couple). Source : fiche source EDN item 38.</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/38/bilan-1ere-intention-fig2.png\" alt=\"Algorithme complémentaire — bilan paraclinique de 1ère intention dans l&#x27;infertilité du couple\" loading=\"lazy\">\n        <figcaption>Vue 2 — algorithme complémentaire du bilan paraclinique 1ʳᵉ intention. Source : fiche source EDN item 38.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"Radiopaedia : Hystérosalpingographie (HSG)"},{"href":"https://radiopaedia.org/articles/testicular-and-scrotal-ultrasound","label":"Radiopaedia : Échographie testiculaire & scrotale"},{"href":"https://radiopaedia.org/cases/scrotal-ultrasound-normal","label":"Radiopaedia : Échographie scrotale normale (cas)"}]},{"id":"38-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes d’interprétation d’un spermogramme","contenu":"<div class=\"notion-course\"><p>Le spermogramme normalisé (<strong>OMS</strong>) est l’examen <strong>pivot</strong> du bilan masculin. À interpréter conjointement avec le <span>spermocytogramme</span> (morphologie) et la <span><span class=\"nc-blue_bg\">spermoculture</span></span> (si suspicion d’<span class=\"nc-purple_bg\">infection</span>).</p>\n\n      <h4>Normes OMS — paramètres clés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Norme OMS</th><th>Anomalie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Couleur</strong></td>\n            <td>Opalescent</td>\n            <td><span>Orangé</span> → suspicion d’<span class=\"nc-purple_bg\">infection</span> (<span class=\"nc-blue nc-bold\">spermoculture</span> indiquée)</td>\n          </tr>\n          <tr>\n            <td><strong>Viscosité</strong></td>\n            <td>Normale</td>\n            <td><span class=\"nc-orange_bg\">Hyperviscosité</span> → témoin d’une <strong><span class=\"nc-orange nc-bold\">insuffisance prostatique</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Volume</strong></td>\n            <td><span>&gt; 1,4 mL</span></td>\n            <td><strong><span class=\"nc-red_bg\">Hypospermie</span></strong> (&lt; <span>1,4 mL</span>) ou <strong><span class=\"nc-red_bg\">aspermie</span></strong> (absence). Évoque vieillissement ou <span>agénésie des déférents</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>pH</span></strong></td>\n            <td><span>7,2 – 8</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Numération</strong></td>\n            <td>&gt; <span>16 M/mL</span> et &gt; <span>39 M / éjaculat</span></td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Oligospermie</span></strong> (&lt; 16 M/mL ou &lt; 39 M/éjaculat) ; <br>\n              <strong><span class=\"nc-red_bg\">Azoospermie</span></strong> = absence totale (frais + culot après centrifugation 3 <span>000 g</span> × <span>15 min</span>) → <span>écho <span class=\"nc-red\">testiculaire</span></span> ; <br>\n              <strong><span class=\"nc-orange_bg\">Cryptospermie</span></strong> (absent à l’état frais, spz dans le culot)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobilité</strong></td>\n            <td>Totale ≥ <span>42 %</span> ; progressive ≥ <span>30 %</span></td>\n            <td><strong><span class=\"nc-red_bg\">Asthénospermie</span></strong> (mobilité progressive &lt; <span>30 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Vitalité</strong></td>\n            <td>&gt; <span>54 %</span></td>\n            <td><strong><span class=\"nc-red_bg\">Nécrospermie</span></strong> (&gt; <span>46 %</span> de spz morts, soit &lt; <span>54 %</span> de vitalité)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Leucocytes</span></strong></td>\n            <td>&lt; <span>1 M/mL</span></td>\n            <td><strong>Leucospermie</strong> (GB &gt; 1 M/mL) → évoque une <span><span class=\"nc-purple nc-bold\">infection</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Agglutinats</strong></td>\n            <td>Absents</td>\n            <td>Présence → <span><span class=\"nc-pink nc-bold\">AC anti-spz</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Spermocytogramme (morphologie)</strong></td>\n            <td>\n              ≥ <span>4 %</span> formes typiques (<strong>Kruger</strong>) ; <br>\n              ≥ <span>23-30 %</span> formes typiques (<strong>David</strong>)\n            </td>\n            <td><strong>Tératospermie</strong> (&lt; <span>4 %</span> Kruger ou &lt; <span>23-30 %</span> David)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>OATS</strong> (oligo-asthéno-tératospermie) = association <strong>≥ <span <span=\"\">&gt;2</span> anomalies</strong> sur <strong><span>≥ 2</span> spermogrammes à <span><span class=\"nc-pink nc-bold\">3 mois</span></span><span class=\"nc-pink nc-bold\"> d’intervalle</span></strong>. C’est l’entité de loin la plus fréquente chez l’homme infécond.\n      </div>\n\n      <h4>Explorations à enchaîner après spermogramme anormal</h4>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Bilan</span> hormonal</strong></td>\n            <td>\n              <span class=\"nc-yellow_bg\">Minimal</span> <span class=\"nc-yellow_bg\">(</span><span><span class=\"nc-yellow_bg\">systématique</span></span> <span class=\"nc-yellow_bg\">si azoospermie sécrétoire ou oligospermie &lt; 10 M/mL</span>) = <span><span class=\"nc-blue_bg\">Testostérone totale,</span> LH, <span class=\"nc-blue_bg\">FSH</span></span> ; <br>\n              <span><span class=\"nc-blue_bg\">Prolactine</span></span> si troubles de la libido + <span class=\"nc-blue_bg\">dysfonction sexuelle</span>, <span class=\"nc-red nc-bold\">gynécomastie inexpliquée</span>, ou insuffisance gonadotrope\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span> scrotale</strong></td>\n            <td>ATCD de pathologie <span class=\"nc-red\">testiculaire</span>, anomalie de l’examen clinique, anomalie au spermogramme</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Caryotype</span></strong></td>\n            <td>\n              Anomalies chez <span>7 %</span> des hommes infertiles (dont 2/3 de <span class=\"nc-red\">Klinefelter</span> XXY). Indiqué si : <br>\n              · <span class=\"nc-brown_bg\">Infertilité inexpliquée</span> ; <br>\n              · <strong><span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span></strong> (<span>17 %</span> d’anomalies) ; <br>\n              · <strong><span class=\"nc-yellow_bg\">Oligospermie &lt; 10 M/mL</span></strong> (≈ <span>10 %</span> si &lt; 5 M ; ≈ <span>4 %</span> entre 5-10 M) ; <br>\n              · Histoire familiale d’avortement à répétition, malformations, retards mentaux\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microdélétions du chromosome Y</strong></td>\n            <td>≈ <span>2 %</span> des hommes avec <span class=\"nc-red_bg\">azoospermie</span>. Indiqué si <span><span class=\"nc-yellow_bg\">azoospermie sécrétoire</span></span> ou <span><span class=\"nc-orange_bg\">oligospermie</span> sévère &lt; 1 M/mL</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mutations du gène CFTR</strong></td>\n            <td>\n              Indications : <span><span class=\"nc-blue_bg\">absence bilatérale des canaux déférents</span></span> et/ou <span class=\"nc-blue_bg\">symptômes de mucoviscidose</span> ; <br>\n              <span>Recherche obligatoire chez la partenaire</span> si mutation chez l’homme (conseil <span>génétique</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 162 — IST</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":2},{"id":"38-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’infertilité chez la femme","contenu":"<div class=\"notion-course\"><p>Cinq grandes catégories étiologiques. À mémoriser dans <strong>l’ordre de fréquence</strong> (<span class=\"nc-yellow_bg\">anovulation</span> &gt; tubaire &gt; <span class=\"nc-orange_bg\">endométriose</span> &gt; utérine ≈ cervicale).</p>\n\n      <h4>1. Anovulations / dysovulations <span>(40 %)</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Anovulation</span></strong> (<span>20 %</span> des infécondités) — aménorrhée ou irrégularités menstruelles (attention : cycles réguliers n’éliminent pas une <span class=\"nc-yellow_bg\">anovulation</span>)</li>\n        <li><strong><span class=\"nc-yellow_bg\">Dysovulations</span></strong> — <span><span class=\"nc-blue nc-bold\">phase lutéale courte ou défectueuse</span></span>, avec <span class=\"nc-pink nc-bold\">sécrétion insuffisante de progestérone</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Étiologies par ordre de fréquence décroissante :</strong> <br>\n        <span><span class=\"nc-orange_bg\">SOPK</span></span> &gt; <span class=\"nc-orange_bg\">hyperprolactinémie</span> &gt; baisse de la réserve ovarienne (voire <span><span class=\"nc-orange_bg\">IOP</span></span>) &gt; déficit gonadotrope d’origine <span class=\"nc-orange_bg\">hypophysaire</span> &gt; déficit gonadotrope d’origine <span class=\"nc-orange_bg\">hypothalamique</span> (surtout psychonutritionnelle)\n      </div>\n\n      <h4>2. Étiologies tubo-péritonéales <span>(30 %)</span> — <strong>cause majeure</strong></h4>\n\n      <ul>\n        <li><strong>Obstacle tubaire :</strong> <span><span class=\"nc-orange_bg\">salpingite</span></span> (Chlamydia ++, parfois passée inaperçue), <span class=\"nc-orange_bg\">traumatisme chirurgical</span>, <span class=\"nc-orange_bg\">endométriose</span></li>\n        <li><strong>Examens diagnostiques :</strong>\n          <ul>\n            <li><span><span class=\"nc-blue_bg\">Hystérosalpingographie</span></span> — montre l’obstacle, ou diverticules évocateurs d’<span class=\"nc-orange_bg\">endométriose</span></li>\n            <li><span>Cœlioscopie avec épreuve au bleu</span> — inventaire des lésions ± gestes thérapeutiques</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Obstacle tubaire bilatéral = indication majeure de FIV</strong> (<span class=\"nc-pink_bg\">fécondation in vitro</span>).\n      </div>\n\n      <h4>3. Endométriose <span>(15 %)</span></h4>\n\n      <ul>\n        <li>Toucherait <span>4 %</span> des femmes, mais retrouvée chez <span>30-50 %</span> des femmes infertiles</li>\n        <li><span>Hystérographie</span> :\n          <ul>\n            <li><span class=\"nc-red\">Diverticules du segment interstitiel des trompes</span> — images en <span>« boule de gui »</span></li>\n            <li><span class=\"nc-red\">Images d’angulation ou de rétention ampullaire</span></li>\n          </ul>\n        </li>\n        <li><span><span class=\"nc-blue_bg\">IRM pelvienne</span></span> — indiquée pour bilan des lésions (anomalie HSG / écho pelvienne)</li>\n        <li><span>Cœlioscopie</span> si HSG normale et signes d’appel — foyers d’<span class=\"nc-orange_bg\">endométriose</span> (<span><span class=\"nc-red\">grains bleutés</span></span>)</li>\n      </ul>\n\n      <h4>4. Étiologies utérines <span>(4 %)</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-red_bg\">Cloisonnement</span>, synéchies</strong> (infectieuses ou post-manœuvres endo-utérines post-partum / post-IVG)</li>\n        <li><strong><span class=\"nc-red_bg\">Polypes muqueux</span>, <span class=\"nc-red_bg\">fibromes sous-muqueux</span>, <span class=\"nc-red_bg\">hyperplasie endométriale</span></strong></li>\n        <li><strong>Démarche diagnostique :</strong>\n          <ul>\n            <li>1ʳᵉ intention : <span><span class=\"nc-yellow_bg\">hystérosalpingographie</span></span>, <span><span class=\"nc-blue_bg\">échographie avec produit de contraste</span></span></li>\n            <li>2ⁿᵈ intention : <span><span class=\"nc-blue_bg\">hystéroscopie</span></span> (diagnostic + traitement possible : synéchie de petite taille)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>5. Étiologies cervicales <span>(4 %)</span></h4>\n\n      <p><span class=\"nc-red_bg\">Sténoses cervicales</span> (post-<strong>conisation</strong>, <strong><span>curetage</span></strong> ou <strong>diathermocoagulation</strong> de l’endocol) → pathologie de la glaire cervicale → <span><span class=\"nc-green_bg\">indication de choix aux inséminations intra-utérines avec sperme du conjoint</span> (IAC)</span>.</p>\n\n      <h4>6. Sexologiques <span>(2 %)</span></h4>\n\n      <ul>\n        <li>Vaginisme, dyspareunie, dysfonction érectile chez le partenaire</li>\n        <li>Optimisation des chances : rapports <strong><span><span class=\"nc-pink nc-bold\">1 jour</span></span><span class=\"nc-pink nc-bold\"> sur 2</span></strong>, fenêtre de fertilité = <span><span class=\"nc-pink nc-bold\">5 jours précédant l’ovulation</span></span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 124 — Ménopause - andropause · 244 — Adénome hypophysaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":0},{"id":"38-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’infertilité chez l’homme","contenu":"<div class=\"notion-course\"><p>Trois grandes catégories étiologiques chez l’homme, qu’il faut savoir <strong>discriminer sur le couple <span>Volume <span class=\"nc-red\">testiculaire</span> / FSH</span></strong> (synthèse stratégique).</p>\n\n      <h4>Synthèse — discrimination par volume <span class=\"nc-red\">testiculaire</span> et FSH</h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Volume testiculaire</th><th>FSH</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span></strong> (non-obstructive)</td>\n            <td><span class=\"nc-green_bg\">Normal</span> ou <span><span class=\"nc-blue_bg nc-bold\">&lt; 10 mL</span></span> (presque toujours sécrétoire si vol <span class=\"nc-blue_bg nc-bold\">&lt; </span><span><span class=\"nc-blue_bg nc-bold\">10 mL</span></span>)</td>\n            <td>\n              <strong><span class=\"nc-red_bg\">FSH élevée</span> (le plus souvent)</strong> → <span class=\"nc-yellow_bg\">atteinte testiculaire</span> ; <br>\n              <strong><span class=\"nc-blue_bg\">FSH</span> basse/normale + <span class=\"nc-pink\">testostérone</span> basse</strong> → atteinte <span><span class=\"nc-blue nc-bold\">centrale</span></span> (signes d’hypogonadisme au 1er plan)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Azoospermie excrétoire</strong> (obstructive)</td>\n            <td><span class=\"nc-green_bg\">Normal</span> (spermatogénèse normale)</td>\n            <td>Normale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>1. <span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span> (non-obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> défaut de spermatogenèse (absence de production par les testicules).</p>\n\n      <table>\n        <thead>\n          <tr><th>FSH</th><th>Mécanisme + bilan</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red_bg\">FSH élevée</span></strong> (origine <span class=\"nc-red\">testiculaire</span> — <span>60 %</span> des azoospermies sécrétoires)</td>\n            <td>\n              ATCD : <span><span class=\"nc-red\">cryptorchidie</span> ++</span>, séquelles d’<span class=\"nc-red\">oreillons</span>… ; <br>\n              <span><span class=\"nc-blue_bg\">Échographie testiculaire</span></span> : éliminer <span class=\"nc-red\">cancer</span> <span class=\"nc-red\">testiculaire</span> ou <span class=\"nc-red\">varicocèle</span> ; <br>\n              <strong><span class=\"nc-blue_bg\">Caryotype</span></strong> (systématique 1ʳᵉ intention) : <span><span class=\"nc-red_bg\">syndrome de Klinefelter</span></span> (volume <span class=\"nc-red\">testiculaire</span> &lt; <span>1-2 mL</span>) ; <br>\n              <strong>Recherche microdélétions du chromosome Y</strong> : doit être réalisée\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">FSH</span> normale ou basse</strong> + testostérone basse + LH normales/basses (atteinte <span class=\"nc-blue nc-bold\">centrale</span>, plus rare)</td>\n            <td>\n              Hypogonadisme <span class=\"nc-orange_bg\">hypothalamique</span> ou <span class=\"nc-orange_bg\">hypophysaire</span> ; <br>\n              <strong>Clinique :</strong> signes d’hypogonadisme au 1er plan (<span class=\"nc-blue_bg\">retard de puberté</span>, <span class=\"nc-blue_bg\">dysfonction sexuelle</span>, <span class=\"nc-blue_bg\">infertilité</span>) ; <br>\n              <strong>Étiologies :</strong> <span><span class=\"nc-orange_bg\">Syndrome de Kallmann-de-Morsier</span></span>, <span><span class=\"nc-orange_bg\">tumeurs hypophysaires</span></span> ; <br>\n              <strong>PEC :</strong> curable par <span><span class=\"nc-pink_bg\">gonadotrophines exogènes</span></span> (simple)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Azoospermie excrétoire (obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> <span class=\"nc-yellow_bg\">obstacle bilatéral sur les voies excrétrices</span> (<span><span class=\"nc-purple nc-bold\">épididyme</span>, <span class=\"nc-purple nc-bold\">canaux déférents</span>, <span class=\"nc-purple nc-bold\">canaux éjaculateurs</span></span>) — spermatogénèse normale.</p>\n\n      <table>\n        <thead>\n          <tr><th>Démarche</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>Dilatation épididymaire bilatérale ; anomalies (absence, <span>nodule</span>, dilatation) des voies séminales</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span>Échographie scrotale</span> + organes génitaux internes (précise le site de l’obstruction)</td>\n          </tr>\n          <tr>\n            <td><strong>Causes acquises</strong></td>\n            <td>\n              <strong>Infectieuses +++</strong> (gonocoque, Chlamydia présumés) ; <br>\n              <span class=\"nc-pink nc-bold\">Chirurgicales</span>, <span class=\"nc-pink nc-bold\">traumatiques</span> (ex. hernie inguine/scrotale, rare) ; <br>\n              Déférent souvent palpable, parfois gros / nodulaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes congénitales</strong></td>\n            <td>\n              <span><span class=\"nc-red_bg\">Agénésies bilatérales des canaux déférents</span> (+++)</span> = <span class=\"nc-red nc-bold\">anomalie biallélique du gène </span><strong><span class=\"nc-red nc-bold\">CFTR</span></strong> (Cystic Fibrosis Transmembrane Regulator, ABCC7), aussi responsable de la <span><span class=\"nc-orange_bg\">mucoviscidose</span></span> : <br>\n              · Non-perception des déférents à la palpation + distension de la tête épididymaire + atrophie du corps ; <br>\n              · Si forme sévère : anomalies pancréas exocrine + <span class=\"nc-red nc-bold\">infections bronchopulmonaires sévères</span> + agénésie bilatérale = <span class=\"nc-orange_bg\">mucoviscidose</span> typique ; <br>\n              · Si forme génitale isolée : <span>analyse moléculaire CFTR</span> pour confirmer + conseil <span>génétique</span> + <strong><span class=\"nc-blue_bg\">exploration de la</span> <span class=\"nc-blue_bg nc-bold\">conjointe</span></strong> (fréquence élevée de mutations hétérozygotes en population générale)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Oligo-asthéno-térato-spermie (OATS) — la plus fréquente</h4>\n\n      <p>Groupe <strong>hétérogène</strong>, de loin le plus fréquent chez l’homme infécond. Associe sur <span>≥ 2</span> spermogrammes : <span class=\"nc-yellow_bg\">anomalies quantitatives</span> <strong>et/ou</strong> qualitatives (<span class=\"nc-red nc-bold\">mobilité</span>, <span class=\"nc-red nc-bold\">vitalité</span>, % formes normales).</p>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD</strong></td>\n            <td><span><span class=\"nc-orange_bg\">Varicocèle</span></span>, <span class=\"nc-orange_bg\">infectieuses</span>, <span><span class=\"nc-orange_bg\">cryptorchidie</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Génétiques</strong></td>\n            <td><span class=\"nc-orange_bg\">Anomalies du caryotype</span>, <span>microdélétion Y AZFc</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mode de vie</strong></td>\n            <td><strong><span><span class=\"nc-red nc-bold\">Tabac</span></span>, <span class=\"nc-red nc-bold\">cannabis</span>, <span><span class=\"nc-red nc-bold\">alcool</span></span></strong>, <span>hamams trop fréquents</span> (chaleur ++)</td>\n          </tr>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td><span class=\"nc-blue nc-bold\">Pesticides</span>, hydrocarbures, solvants, perturbateurs endocriniens</td>\n          </tr>\n          <tr>\n            <td><strong>Idiopathique</strong></td>\n            <td>≈ <span>40 %</span> des cas — aucune cause retrouvée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Enquête étiologique en cas d’OAT extrême</strong> (&lt; <span>5 × 10⁶ spz/mL</span>, chez <span>10 %</span> des patients) : <br>\n        1. <strong><span class=\"nc-blue_bg\">Caryotype</span></strong> systématique ; <br>\n        2. <strong><span class=\"nc-blue_bg\">Microdélétions du bras long du chromosome Y</span></strong> si <span class=\"nc-blue_bg\">caryotype</span> <span class=\"nc-green_bg\">normal</span>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales.</strong> <span>Prostatite chronique</span> et <span>épididymite</span> n’ont <strong>pas de lien prouvé</strong> avec les OATS — contrairement à l’<span><span class=\"nc-purple_bg\">orchite</span></span> (post-<span class=\"nc-red\">oreillons</span> ++).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li><li><a href=\"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Infertilité, RPC 2022</a></li></ul></details>","frequence":3}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"radiopaedia.org"},{"href":"https://fr.wikipedia.org/wiki/Orchidom%C3%A8tre","label":"fr.wikipedia.org"},{"href":"https://radiopaedia.org/articles/testicular-and-scrotal-ultrasound","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/scrotal-ultrasound-normal","label":"radiopaedia.org"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/rpc/","label":"CNGOF · Recommandations pour la pratique clinique"},{"href":"https://cngof.fr/app/uploads/2026/02/RPC-INFERTILITE-2022.pdf","label":"CNGOF · Infertilité, RPC 2022"}],"cards":[{"i":"48a0d893264c","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Quelle est la définition de la fécondabilité d'un couple et son ordre de grandeur ?","a":"<div class=\"notion-course\"><ul><li><b>Fertilité :</b> capacité biologique à concevoir. Elle est potentielle et ne se résume pas au nombre d’enfants déjà nés.</li><li><b>Fécondité :</b> réalisation effective de la reproduction, appréciée notamment par les naissances. En démographie, les indicateurs de fécondité mesurent les naissances dans une population.</li><li><b>Fécondabilité :</b> probabilité d’obtenir une grossesse au cours d’un cycle exposé. Ne pas la confondre avec la probabilité cumulée sur six ou douze mois.</li><li>L’âge ovocytaire influence fortement la fécondabilité et le risque de fausse couche ; la baisse s’accentue avec l’âge, notamment après 35 ans. Les probabilités dépendent aussi de la durée des essais et des facteurs féminins et masculins.</li></ul></div>"},{"i":"e6391ed62615","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Quelle est la définition de la fertilité pour un couple et quels sont les ordres de grandeur à retenir en fonction de l'âge ?","a":"<div class=\"notion-course\"><ul><li><b>Fertilité :</b> capacité biologique à concevoir. Elle est potentielle et ne se résume pas au nombre d’enfants déjà nés.</li><li><b>Fécondité :</b> réalisation effective de la reproduction, appréciée notamment par les naissances. En démographie, les indicateurs de fécondité mesurent les naissances dans une population.</li><li><b>Fécondabilité :</b> probabilité d’obtenir une grossesse au cours d’un cycle exposé. Ne pas la confondre avec la probabilité cumulée sur six ou douze mois.</li><li>L’âge ovocytaire influence fortement la fécondabilité et le risque de fausse couche ; la baisse s’accentue avec l’âge, notamment après 35 ans. Les probabilités dépendent aussi de la durée des essais et des facteurs féminins et masculins.</li></ul></div>"},{"i":"ec906d671cc7","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Comment définit-on la fécondité d'un couple ?","a":"<div class=\"notion-course\"><ul><li><b>Fertilité :</b> capacité biologique à concevoir. Elle est potentielle et ne se résume pas au nombre d’enfants déjà nés.</li><li><b>Fécondité :</b> réalisation effective de la reproduction, appréciée notamment par les naissances. En démographie, les indicateurs de fécondité mesurent les naissances dans une population.</li><li><b>Fécondabilité :</b> probabilité d’obtenir une grossesse au cours d’un cycle exposé. Ne pas la confondre avec la probabilité cumulée sur six ou douze mois.</li><li>L’âge ovocytaire influence fortement la fécondabilité et le risque de fausse couche ; la baisse s’accentue avec l’âge, notamment après 35 ans. Les probabilités dépendent aussi de la durée des essais et des facteurs féminins et masculins.</li></ul></div>"},{"i":"2b12f6298f92","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quelle est la définition de l'infertilité du couple selon l'OMS ?","a":"<div class=\"notion-course\"><ul><li><b>Infertilité :</b> absence de grossesse après au moins douze mois de rapports réguliers sans contraception. <b>Primaire :</b> aucune grossesse antérieure ; <b>secondaire :</b> après une grossesse antérieure, quelle qu’en ait été l’issue.</li><li><b>Bilan plus précoce :</b> à six mois lorsque la femme a plus de 35 ans, et sans attendre ce délai si aménorrhée, pathologie tubaire ou masculine connue, traitement gonadotoxique ou autre facteur majeur. Au-delà de 40 ans, une évaluation rapide est justifiée.</li><li>Évaluer les deux partenaires simultanément : antécédents, durée des essais, cycles, <span class=\"nc-green_bg\">fréquence des rapports</span>, difficultés sexuelles et facteurs de risque. Des rapports réguliers, environ tous les deux à trois jours, évitent un calendrier trop contraignant.</li><li>Infertilité ne signifie pas stérilité définitive ; le bilan et le pronostic dépendent du contexte.</li></ul></div>"},{"i":"3c3a6d811817","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quel est l'objectif principal de la définition opérationnelle de l'infertilité en pratique clinique ?","a":"<div class=\"notion-course\"><ul><li><b>Infertilité :</b> absence de grossesse après au moins douze mois de rapports réguliers sans contraception. <b>Primaire :</b> aucune grossesse antérieure ; <b>secondaire :</b> après une grossesse antérieure, quelle qu’en ait été l’issue.</li><li><b>Bilan plus précoce :</b> à six mois lorsque la femme a plus de 35 ans, et sans attendre ce délai si aménorrhée, pathologie tubaire ou masculine connue, traitement gonadotoxique ou autre facteur majeur. Au-delà de 40 ans, une évaluation rapide est justifiée.</li><li>Évaluer les deux partenaires simultanément : antécédents, durée des essais, cycles, <span class=\"nc-green_bg\">fréquence des rapports</span>, difficultés sexuelles et facteurs de risque. Des rapports réguliers, environ tous les deux à trois jours, évitent un calendrier trop contraignant.</li><li>Infertilité ne signifie pas stérilité définitive ; le bilan et le pronostic dépendent du contexte.</li></ul></div>"},{"i":"44b3b7f2a732","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quand faut-il initier de manière plus précoce le bilan d'infertilité d'un couple ?","a":"<div class=\"notion-course\"><ul><li><b>Infertilité :</b> absence de grossesse après au moins douze mois de rapports réguliers sans contraception. <b>Primaire :</b> aucune grossesse antérieure ; <b>secondaire :</b> après une grossesse antérieure, quelle qu’en ait été l’issue.</li><li><b>Bilan plus précoce :</b> à six mois lorsque la femme a plus de 35 ans, et sans attendre ce délai si aménorrhée, pathologie tubaire ou masculine connue, traitement gonadotoxique ou autre facteur majeur. Au-delà de 40 ans, une évaluation rapide est justifiée.</li><li>Évaluer les deux partenaires simultanément : antécédents, durée des essais, cycles, <span class=\"nc-green_bg\">fréquence des rapports</span>, difficultés sexuelles et facteurs de risque. Des rapports réguliers, environ tous les deux à trois jours, évitent un calendrier trop contraignant.</li><li>Infertilité ne signifie pas stérilité définitive ; le bilan et le pronostic dépendent du contexte.</li></ul></div>"},{"i":"79e8ba29bed3","n":38,"o":"38-3","u":"Epidémiologie, prévalence","t":"Connaître la fertilité et fécondité dans la population générale","q":"Que retenir concernant la fertilité et fécondité dans la population générale ?","a":"<div class=\"notion-course\"><p>La fertilité spontanée du couple est <strong>fortement dépendante de l’âge maternel</strong>. La <span class=\"nc-red nc-bold\">réserve ovarienne en follicules ovariens diminue </span><span><span class=\"nc-red nc-bold\">de façon physiologique avec l’âge en qualité et quantité</span></span> — phénomène irréversible.</p>\n\n      <h4>Courbe de fertilité féminine selon l’âge</h4>\n\n      \n\n      <table>\n        <thead>\n          <tr><th>Âge maternel</th><th>Probabilité de grossesse à <span>6 mois</span></th><th>Commentaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span> 25-28 ans</span></strong></td>\n            <td><span>60 %</span></td>\n            <td>Pic de fertilité ; recul de l’âge à la 1ʳᵉ <span>grossesse</span> = enjeu démographique</td>\n          </tr>\n          <tr>\n            <td><strong><span>31 ans</span></strong></td>\n            <td>—</td>\n            <td><span>Début du déclin</span> (mesurable mais lent)</td>\n          </tr>\n          <tr>\n            <td><strong><span>35 ans</span></strong></td>\n            <td><span>30 %</span></td>\n            <td>Chute marquée — seuil opérationnel pour <strong>raccourcir le délai avant bilan</strong></td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span> 45 ans</span></strong></td>\n            <td><span>≈ 0 %</span></td>\n            <td>Fertilité <span>presque nulle</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs pronostiques principaux (femme)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Facteur</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Réserve ovarienne décroît qualitativement et quantitativement</td>\n          </tr>\n          <tr>\n            <td><strong>Poids</strong></td>\n            <td>\n              <strong>IMC <span class=\"nc-red nc-bold\">&gt;</span><span><span class=\"nc-red nc-bold\"> 30 kg/m²</span></span> :</strong> chances de <span>grossesse</span> divisées par <span>4</span> ; <br>\n              <strong>IMC <span class=\"nc-red nc-bold\">trop bas</span> :</strong> troubles de l’ovulation (<span class=\"nc-yellow_bg\">anovulation</span> <span class=\"nc-orange_bg\">hypothalamique</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Tabac</span></strong></td>\n            <td>\n              Diminution dose-dépendante : <span>↑ délai de conception</span> ; <br>\n              ↑ risque de <span>fausses couches, <span class=\"nc-red_bg\">GEU</span>, <span class=\"nc-red_bg\">RCIU</span>, mort fœtale in utero</span> ; <br>\n              ↑ risque de <span><span class=\"nc-orange_bg\">placenta praevia</span>, HRP, RPM</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Fertilité masculine</h4>\n\n      <p>L’âge paternel est <span>également associé à une diminution de la fertilité spontanée</span>, mais <strong>sans seuil précis</strong> (contrairement à la femme). Relation dose-effet entre <strong>IMC élevé</strong> et hypofertilité d’origine masculine.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 124 — Ménopause - andropause</em></p></div>"},{"i":"20d0508ac639","n":38,"o":"38-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez la femme","q":"Que retenir concernant les éléments de l’interrogatoire et de l’examen clinique chez la femme ?","a":"<div class=\"notion-course\"><p>Le bilan d’infertilité chez la femme est <strong>systématique et structuré</strong> en 4 axes : <span>interrogatoire / terrain</span>, <span>symptômes ciblés</span>, <span>examen clinique</span>, <span>dépistage</span>.</p>\n\n      <h4>Interrogatoire — <span>Terrain</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD gynéco-obstétricaux</strong></td>\n            <td>\n              <strong>Gestité, parité :</strong> grossesses antérieures, IVG anciennes (++) ; <br>\n              <strong>IST, <span class=\"nc-orange_bg\">salpingite</span> :</strong> Chlamydia ++ ; <br>\n              <strong><span>Chirurgie</span> pelvienne :</strong> appendicite compliquée, myomectomie (risque d’adhérences) ; <br>\n              <strong>Chirurgie ovarienne :</strong> risque d’<span>insuffisance ovarienne</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span>Diabète, épilepsie, maladies auto-immunes</span> — pouvant retentir sur une future <span>grossesse</span> ou nécessiter une programmation</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux</strong></td>\n            <td>Pathologies génétiques, thrombophilies / ATCD thromboemboliques, ménopause précoce, <span class=\"nc-red\">cancer</span> du sein, <span>diabète</span>…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés (recherche orientée)</h4>\n\n      <ul>\n        <li><strong>Durée et régularité des cycles</strong> → recherche d’un trouble de l’<span>ovulation</span></li>\n        <li><span>Dysménorrhée</span>, <span>dyspareunie profonde</span> → évoque une <strong>endométriose</strong></li>\n        <li><span>Bouffées de chaleur</span> → en faveur d’une <strong>insuffisance ovarienne prématurée (IOP)</strong></li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Général</strong></td>\n            <td>Morphotype, <span>IMC</span>, signes d’<span>hyperandrogénie</span> (hirsutisme, acné), <span>acanthosis nigricans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Recherche d’une <span>galactorrhée</span> s’il existe des troubles du cycle (<strong>hyperprolactinémie</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologique</strong></td>\n            <td>\n              Malformation <span class=\"nc-red nc-bold\">génitale</span> ; <br>\n              Signes indirects d’<span class=\"nc-orange_bg\">endométriose</span> (<span>utérus rétroversé, douleurs au TV</span>) ; <br>\n              Trophicité vaginale, état du col, présence de <span>gros fibromyomes utérins</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Dépistage</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>FCV de <span>dépistage</span></strong> si le dernier date de <span><span class=\"nc-pink nc-bold\">&gt; 3 ans</span></span>. Précède l’<span class=\"nc-blue_bg\">hystéro-salpingographie</span> (interprétation difficile si pathologie cervicale méconnue).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 162 — IST · 244 — Adénome hypophysaire</em></p></div>"},{"i":"2734dbe7671d","n":38,"o":"38-5","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez l’homme","q":"Que retenir concernant les éléments de l’interrogatoire et de l’examen clinique chez l’homme ?","a":"<div class=\"notion-course\"><p>Bilan clinique masculin = <strong>4 axes</strong> : <span>terrain</span> (toxiques, ATCD), symptômes (sexualité), examen (verge / volume <span class=\"nc-red\">testiculaire</span> / <span class=\"nc-red\">varicocèle</span>), distracteurs annales.</p>\n\n      <h4>Interrogatoire — <span>Terrain</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td>Exposition aux <span>toxiques</span> : chaleur, <strong><span class=\"nc-blue nc-bold\">pesticides</span></strong>, <strong>polluants organochlorés</strong>, <span class=\"nc-blue_bg\">hydrocarbures</span>, <span class=\"nc-blue_bg\">solvants</span>, <span class=\"nc-blue_bg\">perturbateurs endocriniens</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxiques personnels</strong></td>\n            <td><span><span class=\"nc-red\">Tabac</span>, <span class=\"nc-red\">cannabis</span></span> ; quantification de l’<span><span class=\"nc-red nc-bold\">alcool</span></span> ; <span>dopage à la <span class=\"nc-pink\">testostérone</span> et/ou <span class=\"nc-pink\">anabolisants</span> (+++)</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD génitaux</strong></td>\n            <td>\n              <strong>Ectopie <span class=\"nc-red\">testiculaire</span> / cryptorchidie (+++)</strong> ; <br>\n              Torsion ou traumatisme <span class=\"nc-red\">testiculaire</span> ; <br>\n              <span class=\"nc-purple_bg\">Infections (</span><span><span class=\"nc-purple_bg\">IST, oreillons</span></span><span class=\"nc-purple_bg\">)</span> ; <br>\n              <span class=\"nc-orange_bg\">ATCD d’</span><span><span class=\"nc-orange_bg\">hernie</span> inguinale bilatérale opérée</span> (<span>lésion</span> des déférents et/ou vascularisation <span class=\"nc-red\">testiculaire</span>) ; <br>\n              Orchidopexie pour torsion du cordon spermatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span><span class=\"nc-orange_bg\">Mucoviscidose</span></span> (sinusites et bronchites à répétition)</td>\n          </tr>\n          <tr>\n            <td><strong>Traitements</strong></td>\n            <td><span>Chimiothérapie</span>, radiothérapie, <strong><span class=\"nc-pink nc-bold\">psychotropes</span></strong>, <strong><span class=\"nc-pink nc-bold\">anticonvulsivants</span></strong>, <strong><span class=\"nc-pink nc-bold\">stéroïdes</span></strong>, <strong>α-bloquants</strong>, <strong>inhibiteurs de la 5α-réductase</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés</h4>\n\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Dysfonction sexuelle</span></span> : troubles de la libido, de l’érection, de l’éjaculation</li>\n        <li>Douleurs uro-génitales → infection (épididymite, <span>prostatite</span>) ou <strong>varicocèle</strong></li>\n        <li>Signes digestifs ou respiratoires → <span>mucoviscidose</span> (à explorer si évocateur)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Morphotype</strong></td>\n            <td>Aspect <span>gynoïde, eunuchoïde</span>, <span class=\"nc-blue_bg\">taille/poids</span>, évaluation de la pilosité, <span class=\"nc-blue_bg\">gynécomastie bilatérale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’hypoandrisme</strong></td>\n            <td><span class=\"nc-blue_bg\">Faible pilosité</span>, <span class=\"nc-blue_bg\">faible </span><span><span class=\"nc-blue_bg\">masse</span></span><span class=\"nc-blue_bg\"> musculaire</span>, <span class=\"nc-blue_bg\">adiposité augmentée</span></td>\n          </tr>\n          <tr>\n            <td><strong>Verge et appareil externe</strong></td>\n            <td>Hypospadias, infection du méat, présence des épididymes, des <span class=\"nc-purple nc-bold\">canaux déférents</span>, cicatrices chirurgicales</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red\">Varicocèle</span></strong></td>\n            <td>Recherché en position debout + <span>manœuvre de Valsalva</span>. <strong>Grader chaque côté</strong> (<span>1, 2 ou 3</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Volume <span class=\"nc-red\">testiculaire</span></strong></td>\n            <td>Mesuré à l’<span>orchidomètre de Prader</span>. Volume normal = <span><span class=\"nc-pink nc-bold\">15-20 mL</span></span>. ≈<span>80 %</span> du volume est constitué par les <strong>tubes séminifères</strong></td>\n          </tr>\n          <tr>\n            <td><strong>TR</strong></td>\n            <td>Non systématique. Recommandé si : ATCD <span>infectieux</span>, hypospermie, anomalie du plasma séminal, suspicion de déficit androgénique, ou âge justifiant la recherche d’un <span class=\"nc-red\">cancer</span> de la prostate</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales (à ne pas rechercher dans ce contexte).</strong>\n        <ul>\n          <li><span>Signe de Prehn</span> → évoque une <strong>orchi-épididymite</strong>, pas une infertilité</li>\n          <li>Gynécomastie <strong>unilatérale</strong> n’oriente pas vers une infertilité (origine endocrinienne ⇒ généralement bilatérale)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p></div>"},{"i":"46c682d2bf21","n":38,"o":"38-6","u":"Étiologies","t":"Connaître l’orientation diagnostique en fonction du contexte et des manifestations associées","q":"Que retenir concernant l’orientation diagnostique en fonction du contexte et des manifestations associées ?","a":"<div class=\"notion-course\"><p>L’orientation étiologique se construit en croisant <strong>répartition des causes</strong>, <strong>facteurs pronostiques majeurs</strong> et <strong>signes d’appel</strong> orientant vers un mécanisme dominant (ovulatoire / tubaire / utérin / cervical / <span class=\"nc-orange_bg\">endométriose</span> / masculin).</p>\n\n      <h4>Répartition des étiologies d’<span class=\"nc-blue_bg\">infertilité</span> féminine (à connaître)</h4>\n\n      \n\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Anovulations / dysovulations</strong></td><td><span>40 %</span></td></tr>\n          <tr><td><strong>Étiologies tubo-péritonéales</strong></td><td><span>30 %</span></td></tr>\n          <tr><td><strong>Endométriose</strong></td><td><span>15 %</span></td></tr>\n          <tr><td>Étiologies cervicales</td><td><span>4 %</span></td></tr>\n          <tr><td>Étiologies utérines</td><td><span>4 %</span></td></tr>\n          <tr><td>Sexologiques (dysfonctions du couple)</td><td><span>2 %</span></td></tr>\n          <tr><td>Autres</td><td><span>5 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’appel → orientation</h4>\n\n      <table>\n        <thead>\n          <tr><th>Signe d’appel</th><th>Mécanisme évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Aménorrhée ou cycles irréguliers</span></td>\n            <td><span><span class=\"nc-yellow_bg\">Anovulation</span></span> (<span>20 %</span> des infécondités) — explorer <span><span class=\"nc-orange_bg\">SOPK</span></span>, <span><span class=\"nc-orange_bg\">hyperprolactinémie</span></span>, <span><span class=\"nc-orange_bg\">IOP</span></span>, déficit gonadotrope</td>\n          </tr>\n          <tr>\n            <td>Cycles réguliers (28 ± j)</td>\n            <td>N’élimine pas une <span class=\"nc-yellow_bg\">anovulation</span> — <span>progestéronémie J22-23</span> obligatoire</td>\n          </tr>\n          <tr>\n            <td>Hirsutisme, acné, acanthosis nigricans</td>\n            <td><span>SOPK</span> ; doser <span>17OH-progestérone</span>, <span><span class=\"nc-blue_bg\">testostérone totale</span></span><span class=\"nc-blue_bg\">,</span> Δ<span <span=\"\">&gt;4</span> androstènedione, SDHEA</td>\n          </tr>\n          <tr>\n            <td>Galactorrhée, troubles du cycle</td>\n            <td><span><span class=\"nc-orange_bg\">Hyperprolactinémie</span></span> (<span>adénome <span class=\"nc-orange_bg\">hypophysaire</span></span>) — <span><span class=\"nc-blue_bg\">prolactine</span></span> + <span><span class=\"nc-blue_bg\">TSH</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Bouffées de chaleur</span></td>\n            <td><span>Insuffisance ovarienne prématurée (IOP)</span></td>\n          </tr>\n          <tr>\n            <td><span>Dysménorrhée, dyspareunie profonde</span>, utérus rétroversé</td>\n            <td><span>Endométriose</span> (<span>4 %</span> population, <span>30-50 %</span> des femmes infertiles)</td>\n          </tr>\n          <tr>\n            <td>ATCD de <span><span class=\"nc-orange_bg\">salpingite</span></span>, <span>Chlamydia</span>, <span>chirurgie</span> pelvienne</td>\n            <td><span>Cause tubaire</span> (cause majeure d’infertilité féminine)</td>\n          </tr>\n          <tr>\n            <td>ATCD de conisation / <span>curetage</span> / diathermo</td>\n            <td>Pathologie cervicale (sténose, glaire) → indication d’<span>IAC</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Des cycles cliniquement réguliers <strong>n’éliminent pas</strong> une <span class=\"nc-yellow_bg\">anovulation</span> — la <span>progestéronémie au 22-23ᵉ jour</span> reste obligatoire dès qu’il existe une suspicion clinique.\n      </div>\n\n      <h4>Facteurs pronostiques majeurs (femme et homme)</h4>\n\n      <ul>\n        <li><strong>Âge</strong> — facteur N°1 chez la femme (effondrement de la réserve folliculaire après <span>35 ans</span>)</li>\n        <li><strong>Poids</strong> — IMC &gt; 30 = ÷4 chances de <span>grossesse</span> ; IMC <span class=\"nc-red nc-bold\">trop bas</span> = troubles de l’ovulation</li>\n        <li><strong><span>Tabac</span></strong> — dose-dépendant, ↑ délai de conception, fausses couches, <span class=\"nc-red_bg\">GEU</span>, <span class=\"nc-red_bg\">RCIU</span>, MFIU</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 244 — Adénome hypophysaire · 124 — Ménopause - andropause</em></p></div>"},{"i":"31b4e35f6fa7","n":38,"o":"38-7","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une infertilité féminine et/ou masculine","q":"Que retenir concernant le bilan de première intention d’une infertilité féminine et/ou masculine ?","a":"<div class=\"notion-course\"><ul><li>Évaluer simultanément les deux partenaires concernés, avec interrogatoire, examen et prise en compte de l’âge, de la durée d’<span class=\"nc-blue_bg\">infertilité</span> et des facteurs de risque.</li><li>Chez la femme : documenter les cycles et l’<span class=\"nc-red nc-bold\">ovulation</span>, <span class=\"nc-yellow_bg\">échographie pelvienne</span>, bilan hormonal ciblé selon contexte ; évaluation tubaire par hystérosalpingographie ou méthode échographique appropriée si indiquée.</li><li><span class=\"nc-blue_bg\">AMH</span> et compte des follicules antraux renseignent sur la réserve ovarienne et surtout la réponse attendue à une stimulation ; ils ne prédisent pas à eux seuls la possibilité d’une grossesse spontanée.</li><li>Chez l’homme : spermogramme/spermocytogramme, avec conditions de recueil ; <span class=\"nc-blue_bg\">spermoculture</span> selon bilan/projet. Un résultat anormal nécessite confirmation et orientation adaptée.</li><li>Le test post-coïtal de Hühner n’est pas recommandé en routine. Pas de cœlioscopie ou d’<span class=\"nc-blue_bg\">hystéroscopie</span> systématique sans indication.</li><li>Orienter plus tôt si âge maternel élevé, aménorrhée, pathologie tubaire, <span class=\"nc-orange_bg\">endométriose</span> significative ou anomalie spermatique sévère ; ne pas imposer un an d’attente dans toutes les situations.</li></ul></div>"},{"i":"851fcf02eef4","n":38,"o":"38-8","u":"Examens complémentaires","t":"Connaître les principes d’interprétation d’un spermogramme","q":"Que retenir concernant les principes d’interprétation d’un spermogramme ?","a":"<div class=\"notion-course\"><p>Le spermogramme normalisé (<strong>OMS</strong>) est l’examen <strong>pivot</strong> du bilan masculin. À interpréter conjointement avec le <span>spermocytogramme</span> (morphologie) et la <span><span class=\"nc-blue_bg\">spermoculture</span></span> (si suspicion d’<span class=\"nc-purple_bg\">infection</span>).</p>\n\n      <h4>Normes OMS — paramètres clés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Norme OMS</th><th>Anomalie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Couleur</strong></td>\n            <td>Opalescent</td>\n            <td><span>Orangé</span> → suspicion d’<span class=\"nc-purple_bg\">infection</span> (<span class=\"nc-blue nc-bold\">spermoculture</span> indiquée)</td>\n          </tr>\n          <tr>\n            <td><strong>Viscosité</strong></td>\n            <td>Normale</td>\n            <td><span class=\"nc-orange_bg\">Hyperviscosité</span> → témoin d’une <strong><span class=\"nc-orange nc-bold\">insuffisance prostatique</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Volume</strong></td>\n            <td><span>&gt; 1,4 mL</span></td>\n            <td><strong><span class=\"nc-red_bg\">Hypospermie</span></strong> (&lt; <span>1,4 mL</span>) ou <strong><span class=\"nc-red_bg\">aspermie</span></strong> (absence). Évoque vieillissement ou <span>agénésie des déférents</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>pH</span></strong></td>\n            <td><span>7,2 – 8</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Numération</strong></td>\n            <td>&gt; <span>16 M/mL</span> et &gt; <span>39 M / éjaculat</span></td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Oligospermie</span></strong> (&lt; 16 M/mL ou &lt; 39 M/éjaculat) ; <br>\n              <strong><span class=\"nc-red_bg\">Azoospermie</span></strong> = absence totale (frais + culot après centrifugation 3 <span>000 g</span> × <span>15 min</span>) → <span>écho <span class=\"nc-red\">testiculaire</span></span> ; <br>\n              <strong><span class=\"nc-orange_bg\">Cryptospermie</span></strong> (absent à l’état frais, spz dans le culot)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobilité</strong></td>\n            <td>Totale ≥ <span>42 %</span> ; progressive ≥ <span>30 %</span></td>\n            <td><strong><span class=\"nc-red_bg\">Asthénospermie</span></strong> (mobilité progressive &lt; <span>30 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Vitalité</strong></td>\n            <td>&gt; <span>54 %</span></td>\n            <td><strong><span class=\"nc-red_bg\">Nécrospermie</span></strong> (&gt; <span>46 %</span> de spz morts, soit &lt; <span>54 %</span> de vitalité)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Leucocytes</span></strong></td>\n            <td>&lt; <span>1 M/mL</span></td>\n            <td><strong>Leucospermie</strong> (GB &gt; 1 M/mL) → évoque une <span><span class=\"nc-purple nc-bold\">infection</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Agglutinats</strong></td>\n            <td>Absents</td>\n            <td>Présence → <span><span class=\"nc-pink nc-bold\">AC anti-spz</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Spermocytogramme (morphologie)</strong></td>\n            <td>\n              ≥ <span>4 %</span> formes typiques (<strong>Kruger</strong>) ; <br>\n              ≥ <span>23-30 %</span> formes typiques (<strong>David</strong>)\n            </td>\n            <td><strong>Tératospermie</strong> (&lt; <span>4 %</span> Kruger ou &lt; <span>23-30 %</span> David)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>OATS</strong> (oligo-asthéno-tératospermie) = association <strong>≥ <span <span=\"\">&gt;2</span> anomalies</strong> sur <strong><span>≥ 2</span> spermogrammes à <span><span class=\"nc-pink nc-bold\">3 mois</span></span><span class=\"nc-pink nc-bold\"> d’intervalle</span></strong>. C’est l’entité de loin la plus fréquente chez l’homme infécond.\n      </div>\n\n      <h4>Explorations à enchaîner après spermogramme anormal</h4>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Bilan</span> hormonal</strong></td>\n            <td>\n              <span class=\"nc-yellow_bg\">Minimal</span> <span class=\"nc-yellow_bg\">(</span><span><span class=\"nc-yellow_bg\">systématique</span></span> <span class=\"nc-yellow_bg\">si azoospermie sécrétoire ou oligospermie &lt; 10 M/mL</span>) = <span><span class=\"nc-blue_bg\">Testostérone totale,</span> LH, <span class=\"nc-blue_bg\">FSH</span></span> ; <br>\n              <span><span class=\"nc-blue_bg\">Prolactine</span></span> si troubles de la libido + <span class=\"nc-blue_bg\">dysfonction sexuelle</span>, <span class=\"nc-red nc-bold\">gynécomastie inexpliquée</span>, ou insuffisance gonadotrope\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span> scrotale</strong></td>\n            <td>ATCD de pathologie <span class=\"nc-red\">testiculaire</span>, anomalie de l’examen clinique, anomalie au spermogramme</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">Caryotype</span></strong></td>\n            <td>\n              Anomalies chez <span>7 %</span> des hommes infertiles (dont 2/3 de <span class=\"nc-red\">Klinefelter</span> XXY). Indiqué si : <br>\n              · <span class=\"nc-brown_bg\">Infertilité inexpliquée</span> ; <br>\n              · <strong><span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span></strong> (<span>17 %</span> d’anomalies) ; <br>\n              · <strong><span class=\"nc-yellow_bg\">Oligospermie &lt; 10 M/mL</span></strong> (≈ <span>10 %</span> si &lt; 5 M ; ≈ <span>4 %</span> entre 5-10 M) ; <br>\n              · Histoire familiale d’avortement à répétition, malformations, retards mentaux\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microdélétions du chromosome Y</strong></td>\n            <td>≈ <span>2 %</span> des hommes avec <span class=\"nc-red_bg\">azoospermie</span>. Indiqué si <span><span class=\"nc-yellow_bg\">azoospermie sécrétoire</span></span> ou <span><span class=\"nc-orange_bg\">oligospermie</span> sévère &lt; 1 M/mL</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mutations du gène CFTR</strong></td>\n            <td>\n              Indications : <span><span class=\"nc-blue_bg\">absence bilatérale des canaux déférents</span></span> et/ou <span class=\"nc-blue_bg\">symptômes de mucoviscidose</span> ; <br>\n              <span>Recherche obligatoire chez la partenaire</span> si mutation chez l’homme (conseil <span>génétique</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 162 — IST</em></p></div>"},{"i":"9a6e6c26f6e8","n":38,"o":"38-9","u":"Étiologies","t":"Connaître les principales causes d’infertilité chez la femme","q":"Que retenir concernant les principales causes d’infertilité chez la femme ?","a":"<div class=\"notion-course\"><p>Cinq grandes catégories étiologiques. À mémoriser dans <strong>l’ordre de fréquence</strong> (<span class=\"nc-yellow_bg\">anovulation</span> &gt; tubaire &gt; <span class=\"nc-orange_bg\">endométriose</span> &gt; utérine ≈ cervicale).</p>\n\n      <h4>1. Anovulations / dysovulations <span>(40 %)</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Anovulation</span></strong> (<span>20 %</span> des infécondités) — aménorrhée ou irrégularités menstruelles (attention : cycles réguliers n’éliminent pas une <span class=\"nc-yellow_bg\">anovulation</span>)</li>\n        <li><strong><span class=\"nc-yellow_bg\">Dysovulations</span></strong> — <span><span class=\"nc-blue nc-bold\">phase lutéale courte ou défectueuse</span></span>, avec <span class=\"nc-pink nc-bold\">sécrétion insuffisante de progestérone</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Étiologies par ordre de fréquence décroissante :</strong> <br>\n        <span><span class=\"nc-orange_bg\">SOPK</span></span> &gt; <span class=\"nc-orange_bg\">hyperprolactinémie</span> &gt; baisse de la réserve ovarienne (voire <span><span class=\"nc-orange_bg\">IOP</span></span>) &gt; déficit gonadotrope d’origine <span class=\"nc-orange_bg\">hypophysaire</span> &gt; déficit gonadotrope d’origine <span class=\"nc-orange_bg\">hypothalamique</span> (surtout psychonutritionnelle)\n      </div>\n\n      <h4>2. Étiologies tubo-péritonéales <span>(30 %)</span> — <strong>cause majeure</strong></h4>\n\n      <ul>\n        <li><strong>Obstacle tubaire :</strong> <span><span class=\"nc-orange_bg\">salpingite</span></span> (Chlamydia ++, parfois passée inaperçue), <span class=\"nc-orange_bg\">traumatisme chirurgical</span>, <span class=\"nc-orange_bg\">endométriose</span></li>\n        <li><strong>Examens diagnostiques :</strong>\n          <ul>\n            <li><span><span class=\"nc-blue_bg\">Hystérosalpingographie</span></span> — montre l’obstacle, ou diverticules évocateurs d’<span class=\"nc-orange_bg\">endométriose</span></li>\n            <li><span>Cœlioscopie avec épreuve au bleu</span> — inventaire des lésions ± gestes thérapeutiques</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Obstacle tubaire bilatéral = indication majeure de FIV</strong> (<span class=\"nc-pink_bg\">fécondation in vitro</span>).\n      </div>\n\n      <h4>3. Endométriose <span>(15 %)</span></h4>\n\n      <ul>\n        <li>Toucherait <span>4 %</span> des femmes, mais retrouvée chez <span>30-50 %</span> des femmes infertiles</li>\n        <li><span>Hystérographie</span> :\n          <ul>\n            <li><span class=\"nc-red\">Diverticules du segment interstitiel des trompes</span> — images en <span>« boule de gui »</span></li>\n            <li><span class=\"nc-red\">Images d’angulation ou de rétention ampullaire</span></li>\n          </ul>\n        </li>\n        <li><span><span class=\"nc-blue_bg\">IRM pelvienne</span></span> — indiquée pour bilan des lésions (anomalie HSG / écho pelvienne)</li>\n        <li><span>Cœlioscopie</span> si HSG normale et signes d’appel — foyers d’<span class=\"nc-orange_bg\">endométriose</span> (<span><span class=\"nc-red\">grains bleutés</span></span>)</li>\n      </ul>\n\n      <h4>4. Étiologies utérines <span>(4 %)</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-red_bg\">Cloisonnement</span>, synéchies</strong> (infectieuses ou post-manœuvres endo-utérines post-partum / post-IVG)</li>\n        <li><strong><span class=\"nc-red_bg\">Polypes muqueux</span>, <span class=\"nc-red_bg\">fibromes sous-muqueux</span>, <span class=\"nc-red_bg\">hyperplasie endométriale</span></strong></li>\n        <li><strong>Démarche diagnostique :</strong>\n          <ul>\n            <li>1ʳᵉ intention : <span><span class=\"nc-yellow_bg\">hystérosalpingographie</span></span>, <span><span class=\"nc-blue_bg\">échographie avec produit de contraste</span></span></li>\n            <li>2ⁿᵈ intention : <span><span class=\"nc-blue_bg\">hystéroscopie</span></span> (diagnostic + traitement possible : synéchie de petite taille)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>5. Étiologies cervicales <span>(4 %)</span></h4>\n\n      <p><span class=\"nc-red_bg\">Sténoses cervicales</span> (post-<strong>conisation</strong>, <strong><span>curetage</span></strong> ou <strong>diathermocoagulation</strong> de l’endocol) → pathologie de la glaire cervicale → <span><span class=\"nc-green_bg\">indication de choix aux inséminations intra-utérines avec sperme du conjoint</span> (IAC)</span>.</p>\n\n      <h4>6. Sexologiques <span>(2 %)</span></h4>\n\n      <ul>\n        <li>Vaginisme, dyspareunie, dysfonction érectile chez le partenaire</li>\n        <li>Optimisation des chances : rapports <strong><span><span class=\"nc-pink nc-bold\">1 jour</span></span><span class=\"nc-pink nc-bold\"> sur 2</span></strong>, fenêtre de fertilité = <span><span class=\"nc-pink nc-bold\">5 jours précédant l’ovulation</span></span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 124 — Ménopause - andropause · 244 — Adénome hypophysaire</em></p></div>"},{"i":"f7fd82098328","n":38,"o":"38-10","u":"Étiologies","t":"Connaître les principales causes d’infertilité chez l’homme","q":"Que retenir concernant les principales causes d’infertilité chez l’homme ?","a":"<div class=\"notion-course\"><p>Trois grandes catégories étiologiques chez l’homme, qu’il faut savoir <strong>discriminer sur le couple <span>Volume <span class=\"nc-red\">testiculaire</span> / FSH</span></strong> (synthèse stratégique).</p>\n\n      <h4>Synthèse — discrimination par volume <span class=\"nc-red\">testiculaire</span> et FSH</h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Volume testiculaire</th><th>FSH</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span></strong> (non-obstructive)</td>\n            <td><span class=\"nc-green_bg\">Normal</span> ou <span><span class=\"nc-blue_bg nc-bold\">&lt; 10 mL</span></span> (presque toujours sécrétoire si vol <span class=\"nc-blue_bg nc-bold\">&lt; </span><span><span class=\"nc-blue_bg nc-bold\">10 mL</span></span>)</td>\n            <td>\n              <strong><span class=\"nc-red_bg\">FSH élevée</span> (le plus souvent)</strong> → <span class=\"nc-yellow_bg\">atteinte testiculaire</span> ; <br>\n              <strong><span class=\"nc-blue_bg\">FSH</span> basse/normale + <span class=\"nc-pink\">testostérone</span> basse</strong> → atteinte <span><span class=\"nc-blue nc-bold\">centrale</span></span> (signes d’hypogonadisme au 1er plan)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Azoospermie excrétoire</strong> (obstructive)</td>\n            <td><span class=\"nc-green_bg\">Normal</span> (spermatogénèse normale)</td>\n            <td>Normale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>1. <span class=\"nc-yellow_bg\">Azoospermie sécrétoire</span> (non-obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> défaut de spermatogenèse (absence de production par les testicules).</p>\n\n      <table>\n        <thead>\n          <tr><th>FSH</th><th>Mécanisme + bilan</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red_bg\">FSH élevée</span></strong> (origine <span class=\"nc-red\">testiculaire</span> — <span>60 %</span> des azoospermies sécrétoires)</td>\n            <td>\n              ATCD : <span><span class=\"nc-red\">cryptorchidie</span> ++</span>, séquelles d’<span class=\"nc-red\">oreillons</span>… ; <br>\n              <span><span class=\"nc-blue_bg\">Échographie testiculaire</span></span> : éliminer <span class=\"nc-red\">cancer</span> <span class=\"nc-red\">testiculaire</span> ou <span class=\"nc-red\">varicocèle</span> ; <br>\n              <strong><span class=\"nc-blue_bg\">Caryotype</span></strong> (systématique 1ʳᵉ intention) : <span><span class=\"nc-red_bg\">syndrome de Klinefelter</span></span> (volume <span class=\"nc-red\">testiculaire</span> &lt; <span>1-2 mL</span>) ; <br>\n              <strong>Recherche microdélétions du chromosome Y</strong> : doit être réalisée\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-blue_bg\">FSH</span> normale ou basse</strong> + testostérone basse + LH normales/basses (atteinte <span class=\"nc-blue nc-bold\">centrale</span>, plus rare)</td>\n            <td>\n              Hypogonadisme <span class=\"nc-orange_bg\">hypothalamique</span> ou <span class=\"nc-orange_bg\">hypophysaire</span> ; <br>\n              <strong>Clinique :</strong> signes d’hypogonadisme au 1er plan (<span class=\"nc-blue_bg\">retard de puberté</span>, <span class=\"nc-blue_bg\">dysfonction sexuelle</span>, <span class=\"nc-blue_bg\">infertilité</span>) ; <br>\n              <strong>Étiologies :</strong> <span><span class=\"nc-orange_bg\">Syndrome de Kallmann-de-Morsier</span></span>, <span><span class=\"nc-orange_bg\">tumeurs hypophysaires</span></span> ; <br>\n              <strong>PEC :</strong> curable par <span><span class=\"nc-pink_bg\">gonadotrophines exogènes</span></span> (simple)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Azoospermie excrétoire (obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> <span class=\"nc-yellow_bg\">obstacle bilatéral sur les voies excrétrices</span> (<span><span class=\"nc-purple nc-bold\">épididyme</span>, <span class=\"nc-purple nc-bold\">canaux déférents</span>, <span class=\"nc-purple nc-bold\">canaux éjaculateurs</span></span>) — spermatogénèse normale.</p>\n\n      <table>\n        <thead>\n          <tr><th>Démarche</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>Dilatation épididymaire bilatérale ; anomalies (absence, <span>nodule</span>, dilatation) des voies séminales</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span>Échographie scrotale</span> + organes génitaux internes (précise le site de l’obstruction)</td>\n          </tr>\n          <tr>\n            <td><strong>Causes acquises</strong></td>\n            <td>\n              <strong>Infectieuses +++</strong> (gonocoque, Chlamydia présumés) ; <br>\n              <span class=\"nc-pink nc-bold\">Chirurgicales</span>, <span class=\"nc-pink nc-bold\">traumatiques</span> (ex. hernie inguine/scrotale, rare) ; <br>\n              Déférent souvent palpable, parfois gros / nodulaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes congénitales</strong></td>\n            <td>\n              <span><span class=\"nc-red_bg\">Agénésies bilatérales des canaux déférents</span> (+++)</span> = <span class=\"nc-red nc-bold\">anomalie biallélique du gène </span><strong><span class=\"nc-red nc-bold\">CFTR</span></strong> (Cystic Fibrosis Transmembrane Regulator, ABCC7), aussi responsable de la <span><span class=\"nc-orange_bg\">mucoviscidose</span></span> : <br>\n              · Non-perception des déférents à la palpation + distension de la tête épididymaire + atrophie du corps ; <br>\n              · Si forme sévère : anomalies pancréas exocrine + <span class=\"nc-red nc-bold\">infections bronchopulmonaires sévères</span> + agénésie bilatérale = <span class=\"nc-orange_bg\">mucoviscidose</span> typique ; <br>\n              · Si forme génitale isolée : <span>analyse moléculaire CFTR</span> pour confirmer + conseil <span>génétique</span> + <strong><span class=\"nc-blue_bg\">exploration de la</span> <span class=\"nc-blue_bg nc-bold\">conjointe</span></strong> (fréquence élevée de mutations hétérozygotes en population générale)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Oligo-asthéno-térato-spermie (OATS) — la plus fréquente</h4>\n\n      <p>Groupe <strong>hétérogène</strong>, de loin le plus fréquent chez l’homme infécond. Associe sur <span>≥ 2</span> spermogrammes : <span class=\"nc-yellow_bg\">anomalies quantitatives</span> <strong>et/ou</strong> qualitatives (<span class=\"nc-red nc-bold\">mobilité</span>, <span class=\"nc-red nc-bold\">vitalité</span>, % formes normales).</p>\n\n      <table>\n        <thead>\n          <tr><th>Domaine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD</strong></td>\n            <td><span><span class=\"nc-orange_bg\">Varicocèle</span></span>, <span class=\"nc-orange_bg\">infectieuses</span>, <span><span class=\"nc-orange_bg\">cryptorchidie</span></span></td>\n          </tr>\n          <tr>\n            <td><strong>Génétiques</strong></td>\n            <td><span class=\"nc-orange_bg\">Anomalies du caryotype</span>, <span>microdélétion Y AZFc</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mode de vie</strong></td>\n            <td><strong><span><span class=\"nc-red nc-bold\">Tabac</span></span>, <span class=\"nc-red nc-bold\">cannabis</span>, <span><span class=\"nc-red nc-bold\">alcool</span></span></strong>, <span>hamams trop fréquents</span> (chaleur ++)</td>\n          </tr>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td><span class=\"nc-blue nc-bold\">Pesticides</span>, hydrocarbures, solvants, perturbateurs endocriniens</td>\n          </tr>\n          <tr>\n            <td><strong>Idiopathique</strong></td>\n            <td>≈ <span>40 %</span> des cas — aucune cause retrouvée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Enquête étiologique en cas d’OAT extrême</strong> (&lt; <span>5 × 10⁶ spz/mL</span>, chez <span>10 %</span> des patients) : <br>\n        1. <strong><span class=\"nc-blue_bg\">Caryotype</span></strong> systématique ; <br>\n        2. <strong><span class=\"nc-blue_bg\">Microdélétions du bras long du chromosome Y</span></strong> si <span class=\"nc-blue_bg\">caryotype</span> <span class=\"nc-green_bg\">normal</span>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales.</strong> <span>Prostatite chronique</span> et <span>épididymite</span> n’ont <strong>pas de lien prouvé</strong> avec les OATS — contrairement à l’<span><span class=\"nc-purple_bg\">orchite</span></span> (post-<span class=\"nc-red\">oreillons</span> ++).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181128485f0aefb8e42a4?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Depuis combien de temps et à quel âge ?","detail":"<ul><li>Définir infertilité et fécondabilité ; avancer le bilan si âge ou facteur de risque.</li></ul>","branches":[{"label":"Bilan indiqué","to":"couple"},{"label":"Délai court sans facteur de risque","to":"conseils"}]},{"id":"conseils","kind":"finish","label":"Informer et planifier une réévaluation","detail":"<ul><li>Rapports réguliers, santé préconceptionnelle et consultation plus tôt si anomalie.</li></ul>","branches":[]},{"id":"couple","kind":"decision","label":"Interroger et examiner les deux partenaires","detail":"<ul><li>Cycles, chirurgie, infections, traitements, sexualité, antécédents testiculaires.</li></ul>","branches":[{"label":"Explorer en parallèle","to":"bilan"}]},{"id":"bilan","kind":"decision","label":"Spermogramme et bilan féminin ciblé","detail":"<ul><li>Ovulation, échographie ; perméabilité tubaire selon indication. Pas de test post-coïtal systématique.</li></ul>","branches":[{"label":"Anomalie spermatique","to":"homme"},{"label":"Trouble ovulatoire","to":"ovulation"},{"label":"Cause tubaire/utérine ou autre","to":"femme"},{"label":"Bilan initial normal","to":"inexplique"}]},{"id":"homme","kind":"finish","label":"Confirmer et orienter en andrologie","detail":"<ul><li>Interpréter l’ensemble du spermogramme ; une valeur isolée ne prouve pas une stérilité.</li></ul>","branches":[]},{"id":"ovulation","kind":"finish","label":"Identifier la cause endocrinienne","detail":"<ul><li>SOPK, causes centrales, IOP ; bilan adapté aux signes.</li></ul>","branches":[]},{"id":"femme","kind":"finish","label":"Compléter selon hypothèse","detail":"<ul><li>Atteinte tubaire, utérine, endométriose ou réserve ovarienne ; examen invasif si utile.</li></ul>","branches":[]},{"id":"inexplique","kind":"finish","label":"Réévaluer le pronostic du projet","detail":"<ul><li>Âge, durée, examens réellement réalisés et orientation vers centre d’infertilité.</li></ul>","branches":[]}]}};
